from solution import most_occurrences


def test_issue_example_from_description():
    """Example asserts most_occurrences([...]) == 'UTS'."""
    assert most_occurrences(["UTS is best for RTF", "RTF love UTS", "UTS is best"]) == 'UTS'  # UTS:3=1+1+1 > is:2, best:2, RTF:2, for:1, love:1


def test_issue_single_word_list():
    """Rule: get the word with most number of occurrences in the given strings list."""
    assert most_occurrences(["hello"]) == 'hello'  # hello:1 only word


def test_issue_repeated_word_in_single_string():
    """Rule: get the word with most number of occurrences in the given strings list."""
    assert most_occurrences(["hello hello world"]) == 'hello'  # hello:2=1+1 > world:1


def test_issue_aggregates_across_strings():
    """Rule: get the word with most number of occurrences in the given strings list."""
    assert most_occurrences(["a b", "b c", "b d"]) == 'b'  # b:3=1+1+1 > a:1, c:1, d:1


def test_issue_winner_not_in_first_string():
    """Rule: get the word with most number of occurrences in the given strings list."""
    assert most_occurrences(["aaa bbb", "ccc ccc ccc"]) == 'ccc'  # ccc:3=0+3 > aaa:1, bbb:1


def test_issue_empty_string_element_still_finds_winner():
    """Rule: get the word with most number of occurrences in the given strings list."""
    assert most_occurrences(["", "hello hello world"]) == 'hello'  # hello:2=0+2 > world:1=0+1, empty:0 words


def test_issue_tie_returns_one_top_word():
    """Rule: get the word with most number of occurrences in the given strings list."""
    assert most_occurrences(["a b", "b a"]) in {'a', 'b'}  # a:2=1+1 == b:2=1+1 tie, either is most frequent


def test_issue_larger_repeated_counts():
    """Rule: get the word with most number of occurrences in the given strings list."""
    assert most_occurrences(["x x x y y", "y x"]) == 'x'  # x:4=3+1 > y:3=2+1


def test_contract_returns_string_word():
    """Contract: example returns word string 'UTS'."""
    result = most_occurrences(["foo foo bar"])  # foo:2=2+0 > bar:1=1+0, expected 'foo'
    assert isinstance(result, str)


def test_contract_result_is_word_from_input():
    """Contract: get the word in the given strings list."""
    result = most_occurrences(["dog cat dog bird"])  # dog:2 > cat:1, bird:1, expected 'dog'
    assert result in {'dog', 'cat', 'bird'}
